 41→  interface ColumnMeta<TData extends RowData, TValue> {
 42→    search?: {
 43→      "data-cy"?: string;
 44→      placeholder?: string;
 45→    };
 46→    treeSelect?: {
 47→      "data-cy"?: string;
 48→      // Configures whether or not the tree select should be filtered to only represent values found in the table.
 49→      // Note that this may not be very performant for large tables.
 50→      filterOptions?: boolean;
